import{_ as i,o as t,c as s,a4 as a}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse('{"title":"ADR-0061 — Média personnel : un drapeau qui retire le média du public et journalise ses lectures","description":"Extrait de docs/adr/0061-media-personnel.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0061 — Média personnel : un drapeau qui retire le média du public et journalise ses lectures","description":"Extrait de docs/adr/0061-media-personnel.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0061-media-personnel.md","filePath":"developpeurs/adr/0061-media-personnel.md"}'),n={name:"developpeurs/adr/0061-media-personnel.md"};function o(r,e,d,l,u,c){return t(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="adr-0061--média-personnel--un-drapeau-qui-retire-le-média-du-public-et-journalise-ses-lectures" tabindex="-1">ADR-0061 — Média personnel : un drapeau qui retire le média du public et journalise ses lectures <a class="header-anchor" href="#adr-0061--média-personnel--un-drapeau-qui-retire-le-média-du-public-et-journalise-ses-lectures" aria-label="Permalink to &quot;ADR-0061 — Média personnel : un drapeau qui retire le média du public et journalise ses lectures {#adr-0061--média-personnel--un-drapeau-qui-retire-le-média-du-public-et-journalise-ses-lectures}&quot;">​</a></h1><p><strong>Date :</strong> 29 septembre 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> audit complet du 26 septembre 2026, constat RGPD-10 (« Lectures de la médiathèque non journalisées ; aucun drapeau « média personnel » ») <strong>Complète :</strong> <a href="/teuthis-cms-distribution/developpeurs/adr/0041-mediatheque-socle">ADR-0041</a> (médiathèque, décision 10 « Un média est public par nature »), sans en modifier la décision ; s&#39;appuie sur l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0017-fichiers-personnels-adresses-par-identifiant">ADR-0017</a>, l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0044-video-depot-en-flux-et-sous-titres">ADR-0044</a>, l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0049-identite-visuelle-du-site-public">ADR-0049</a> et l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0054-metadonnees-des-images-retirees-au-depot">ADR-0054</a></p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>L&#39;ADR-0041 pose qu&#39;un média est public par nature : qui connaît son identifiant lit ses octets, et un fichier lié à une personne relève des fichiers personnels (ADR-0017). La règle est juste, mais elle ne se contrôle pas : rien n&#39;empêche un agent de déposer dans la médiathèque la photo d&#39;un élu pour un trombinoscope interne, la copie d&#39;une pièce d&#39;identité ou une liste nominative. Ce média sortait alors comme une affiche : fichier, métadonnées, image de partage, recherche. Et aucune lecture de la médiathèque par le back-office n&#39;était journalisée (<code>api/media.py</code>), alors que le Core journalise toute lecture du détail d&#39;un contenu qui porte des données personnelles (CDC §13.1).</p><p>L&#39;audit laissait le choix : un drapeau, ou une règle écrite à l&#39;ADR-0041. Le Product Owner retient le drapeau.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><ol><li><strong>Un booléen <code>contains_personal_data</code> sur <code>media_assets</code></strong>, <code>NOT NULL</code>, <code>false</code> par défaut (migration <code>0043</code>). Les médias déjà déposés restent publics : le drapeau est une décision de l&#39;agent, jamais une supposition. Même nom que le drapeau des types et des champs (CLAUDE.md).</li><li><strong>Le contrat avec le back-office.</strong> Le champ figure dans le détail (<code>GET /media/{id}</code>) <strong>et</strong> dans chaque ligne de la liste (<code>GET /media</code>). Il se pose et se retire par la route de mise à jour existante (<code>PATCH /media/{id}</code>). La liste accepte le filtre <code>contains_personal_data=true|false</code>.</li><li><strong>Tant qu&#39;il est posé, le média n&#39;est jamais servi au public.</strong> Une seule condition SQL, <code>public_media_clause()</code> (<code>app/media/personal.py</code>), lue par <code>get_public_media</code>, <code>get_public_media_batch</code> et <code>get_public_caption</code>. Toutes les surfaces publiques passent par elles : fichier (<code>/public/media/{id}/file</code>), métadonnées d&#39;un lot (<code>/public/media</code>), sous-titres, <code>/public/resolve</code> (<code>seo.image</code> et le dictionnaire <code>media</code> des blocs et champs), flux RSS, logo et favicon du thème et du pied de page. Le média y est <strong>absent</strong>, exactement comme un média inconnu : même 404, même absence dans un lot. Un front ne distingue pas « personnel » de « supprimé ». La condition est posée en base : une surface ajoutée plus tard ne peut pas oublier un filtre applicatif, seulement choisir la mauvaise fonction de lecture.</li><li><strong>Les caches.</strong> Les réponses publiques d&#39;un média personnel sont des 404, que l&#39;intergiciel de cache marque déjà <code>no-store</code> (ADR-0035). Les octets et le détail servis au back-office portent <code>Cache-Control: private, no-store</code> au lieu de la consigne publique et immuable d&#39;un média ordinaire. Un fichier déjà servi publiquement <strong>avant</strong> la pose du drapeau peut rester dans un cache tiers jusqu&#39;à expiration : le drapeau ne rappelle pas une copie.</li><li><strong>Chaque lecture du back-office est journalisée.</strong> Détail (<code>GET /media/{id}</code>, et la réponse d&#39;un <code>PATCH</code>, qui rend ce détail), octets (<code>GET /media/{id}/file</code>, une ligne par réponse qui porte des octets, aucune pour un 304) et sous-titres (nouvelle route authentifiée <code>GET /media/{id}/captions/{caption_id}/file</code>, puisque la route publique les tient pour inconnus) écrivent une ligne <code>personal_data_access_logs</code> au périmètre <code>media:{id}</code>, avec l&#39;agent. Poser ou retirer le drapeau est journalisé aussi (<code>UPDATE</code>). <strong>Une ligne de liste n&#39;est pas journalisée</strong> : la liste montre qu&#39;un média existe, pas ce qu&#39;il contient. Ni le nom du fichier ni son titre ne sont recopiés dans le journal.</li><li><strong>Ni recherche, ni IA.</strong> Poser le drapeau supprime sur-le-champ les lignes d&#39;index du média, dans tous les sites. L&#39;extraction native ne le reprend pas tant qu&#39;il est posé. L&#39;extraction par l&#39;IA le refuse avant toute invocation (<code>personal_media</code>), et une image personnelle n&#39;est jamais confiée à un fournisseur de vision. Retirer le drapeau remet un document inclus dans la recherche en attente d&#39;extraction.</li></ol><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Règle écrite seule à l&#39;ADR-0041</strong> (« ne déposez rien de personnel »)</td><td>Elle existe déjà, et elle n&#39;a rien empêché. Elle ne donne pas non plus de journal des lectures.</td></tr><tr><td><strong>Déplacer le média vers les fichiers personnels (ADR-0017)</strong></td><td>Un fichier personnel a un porteur (<code>subject_kind</code>/<code>subject_id</code>). Un média n&#39;en a pas : il sert à plusieurs contenus, et le déplacer casserait ses usages.</td></tr><tr><td><strong>Filtrer après coup, en Python, dans chaque route publique</strong></td><td>Chaque surface nouvelle devrait s&#39;en souvenir. Une fonction de lecture publique unique ne s&#39;oublie pas.</td></tr><tr><td><strong>Un 403 ou un 410 pour un média personnel</strong></td><td>Il dirait au public qu&#39;un média existe à cet identifiant. Le 404 unique ne dit rien.</td></tr><tr><td><strong>Journaliser aussi les lignes de liste</strong></td><td>Contraire au patron du Core (CLAUDE.md, CDC §13.1). Le journal deviendrait illisible, sans rien apprendre au DPO.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Un média déposé par erreur dans la médiathèque se retire du public en un geste, sans casser les contenus qui le citent : ils perdent l&#39;image, pas leur publication.</li><li>Le DPO sait qui a lu le détail ou le fichier d&#39;un média personnel, et quand.</li><li>Une seule condition à auditer pour toutes les surfaces publiques.</li></ul><p><strong>Négatives</strong></p><ul><li>Une nouvelle surface publique qui lirait <code>media_assets</code> directement, sans <code>get_public_media*</code>, servirait un média personnel. La règle est écrite dans <code>app/media/personal.py</code> et <code>app/media/service.py</code>, et les tests <code>tests/test_media_personnel.py</code> couvrent chaque surface actuelle.</li><li>Le drapeau ne rappelle pas les copies déjà servies publiquement : caches tiers et navigateurs les gardent jusqu&#39;à expiration (un an pour un média ordinaire).</li><li>Le back-office doit lire les sous-titres d&#39;une vidéo personnelle par la route authentifiée, et non plus par l&#39;URL publique.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Colonne et migration <code>0043</code>, champ du détail et de la liste, <code>PATCH</code> et filtre de liste. Preuve : <code>test_le_drapeau_figure_au_detail_et_a_la_liste_et_se_pose_par_patch</code>.</li><li>[x] Surfaces publiques (fichier, lot, sous-titres, <code>/public/resolve</code>, thème et pied de page). Preuve : <code>tests/test_media_personnel.py</code>.</li><li>[x] Journal du détail, du fichier et des sous-titres ; aucune ligne pour la liste. Preuve : <code>test_le_detail_et_le_fichier_d_un_media_personnel_sont_journalises</code>.</li><li>[x] Recherche et IA. Preuve : <code>test_poser_le_drapeau_retire_le_media_de_la_recherche</code>, <code>test_l_extraction_ia_refuse_un_document_personnel_avant_l_invocation</code>.</li><li>[x] Notice d&#39;exploitation, §6.8.</li></ul>',16)])])}const h=i(n,[["render",o]]);export{m as __pageData,h as default};
